    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    if not man_patches:
        return image_patch
    black_jacket_patches = [m for m in man_patches if m.verify_property("jacket", "black")]
    if not black_jacket_patches:
        return man_patches[0]
    snowboarding_patches = [bj for bj in black_jacket_patches if bj.verify_property("activity", "snowboarding")]
    return snowboarding_patches[0] if snowboarding_patches else black_jacket_patches[0]

